content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --transition: all 0.2s ease-in-out;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  margin-bottom: 32px;
  text-align: center;
}

.header h1 {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 8px;
}

.header p {
  color: var(--text-muted);
  font-size: 1rem;
}

.simulator-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 1024px) {
  .simulator-layout {
    grid-template-columns: 420px 1fr;
  }
}

.form-section {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.chart-section {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  margin-top: 24px;
  min-height: 400px;
}

.result-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.summary-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
  border-left: 4px solid var(--primary-color);
}

.summary-title {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 8px;
  font-weight: 500;
}

.summary-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.input {
  width: 100%;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: var(--transition);
  background-color: #fff;
  color: var(--text-main);
}

.input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.slider {
  width: 100%;
  height: 6px;
  background: var(--border-color);
  border-radius: 3px;
  outline: none;
  -webkit-appearance: none;
  margin-top: 6px;
}

.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--primary-color);
  cursor: pointer;
  transition: var(--transition);
}

.slider::-webkit-slider-thumb:hover {
  transform: scale(1.1);
}

.value-display {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--primary-color);
}

.radio-group {
  display: flex;
  gap: 16px;
  margin-top: 4px;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.95rem;
  cursor: pointer;
  user-select: none;
}

.radio-label input[type="radio"] {
  accent-color: var(--primary-color);
  width: 16px;
  height: 16px;
  cursor: pointer;
}

export interface LoanInput {
  amount: number;
  interestRate: number;
  years: number;
  repaymentType: string;
}

export interface YearlySchedule {
  year: number;
  balance: number;
  principal: number;
  interest: number;
  totalPaid: number;
}

export interface LoanFormProps {
  input: LoanInput;
  onChange: (input: LoanInput) => void;
}

export interface LoanChartProps {
  schedule: YearlySchedule[];
}

export interface LoanSummaryProps {
  input: LoanInput;
  monthlyPayment: number;
  totalInterest: number;
  totalPayment: number;
  firstMonthPayment: number;
  lastMonthPayment: number;
}

import { LoanFormProps } from "../types";
import "../index.css";

export default function LoanForm({ input, onChange }: LoanFormProps) {
  const handleChange = (field: string, value: any) => {
    onChange({
      ...input,
      [field]: value,
    });
  };

  return (
    <div className="form-section">
      <div className="input-group">
        <label className="label">
          <span>借入金額</span>
          <span className="value-display">{(input.amount / 10000).toLocaleString()} 万円</span>
        </label>
        <input
          type="number"
          className="input"
          value={input.amount}
          step={100000}
          min={1000000}
          max={200000000}
          onChange={(e) => handleChange("amount", Number(e.target.value))}
        />
        <input
          type="range"
          className="slider"
          min={1000000}
          max={100000000}
          step={1000000}
          value={input.amount}
          onChange={(e) => handleChange("amount", Number(e.target.value))}
        />
      </div>

      <div className="input-group">
        <label className="label">
          <span>金利 (年利)</span>
          <span className="value-display">{input.interestRate.toFixed(2)} %</span>
        </label>
        <input
          type="number"
          className="input"
          value={input.interestRate}
          step={0.01}
          min={0.01}
          max={10.0}
          onChange={(e) => handleChange("interestRate", Number(e.target.value))}
        />
        <input
          type="range"
          className="slider"
          min={0.1}
          max={5.0}
          step={0.05}
          value={input.interestRate}
          onChange={(e) => handleChange("interestRate", Number(e.target.value))}
        />
      </div>

      <div className="input-group">
        <label className="label">
          <span>返済期間</span>
          <span className="value-display">{input.years} 年</span>
        </label>
        <input
          type="number"
          className="input"
          value={input.years}
          step={1}
          min={1}
          max={50}
          onChange={(e) => handleChange("years", Number(e.target.value))}
        />
        <input
          type="range"
          className="slider"
          min={1}
          max={50}
          step={1}
          value={input.years}
          onChange={(e) => handleChange("years", Number(e.target.value))}
        />
      </div>

      <div className="input-group">
        <label className="label">
          <span>返済方式</span>
        </label>
        <div className="radio-group">
          <label className="radio-label">
            <input
              type="radio"
              name="repaymentType"
              value="equal-principal-and-interest"
              checked={input.repaymentType === "equal-principal-and-interest"}
              onChange={(e) => handleChange("repaymentType", e.target.value)}
            />
            元利均等
          </label>
          <label className="radio-label">
            <input
              type="radio"
              name="repaymentType"
              value="equal-principal"
              checked={input.repaymentType === "equal-principal"}
              onChange={(e) => handleChange("repaymentType", e.target.value)}
            />
            元金均等
          </label>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo } from "react";
import { LoanInput, YearlySchedule } from "./types";
import LoanForm from "./components/LoanForm";
import LoanChart from "./components/LoanChart";
import "./index.css";

export default function App() {
  const [input, setInput] = useState<LoanInput>({
    amount: 35000000,
    interestRate: 1.2,
    years: 35,
    repaymentType: "equal-principal-and-interest",
  });

  const { schedule, monthlyPayment, totalInterest, totalPayment, firstMonthPayment, lastMonthPayment } =
    useMemo(() => {
      const p = input.amount;
      const r = input.interestRate / 100 / 12;
      const n = input.years * 12;
      const type = input.repaymentType;

      let balance = p;
      let totalInterestCalc = 0;
      let totalPaymentCalc = 0;
      let firstMonth = 0;
      let lastMonth = 0;

      const sched: YearlySchedule[] = [];
      let yearlyPrincipal = 0;
      let yearlyInterest = 0;

      if (type === "equal-principal-and-interest") {
        const pmt = r === 0 ? p / n : (p * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
        firstMonth = pmt;

        for (let month = 1; month <= n; month++) {
          const interest = balance * r;
          let principal = pmt - interest;
          if (month === n) {
            principal = balance;
          }
          balance -= principal;
          totalInterestCalc += interest;
          totalPaymentCalc += principal + interest;

          yearlyPrincipal += principal;
          yearlyInterest += interest;

          if (month === n) {
            lastMonth = principal + interest;
          }

          if (month % 12 === 0 || month === n) {
            const year = Math.ceil(month / 12);
            sched.push({
              year,
              balance: Math.max(0, Math.round(balance)),
              principal: Math.round(yearlyPrincipal),
              interest: Math.round(yearlyInterest),
              totalPaid: Math.round(totalPaymentCalc),
            });
            yearlyPrincipal = 0;
            yearlyInterest = 0;
          }
        }
      } else {
        const monthlyPrincipal = p / n;
        for (let month = 1; month <= n; month++) {
          const interest = balance * r;
          const principal = monthlyPrincipal;
          balance -= principal;
          const payment = principal + interest;

          if (month === 1) firstMonth = payment;
          if (month === n) lastMonth = payment;

          totalInterestCalc += interest;
          totalPaymentCalc += payment;

          yearlyPrincipal += principal;
          yearlyInterest += interest;

          if (month % 12 === 0 || month === n) {
            const year = Math.ceil(month / 12);
            sched.push({
              year,
              balance: Math.max(0, Math.round(balance)),
              principal: Math.round(yearlyPrincipal),
              interest: Math.round(yearlyInterest),
              totalPaid: Math.round(totalPaymentCalc),
            });
            yearlyPrincipal = 0;
            yearlyInterest = 0;
          }
        }
      }

      return {
        schedule: sched,
        monthlyPayment: Math.round(firstMonth),
        totalInterest: Math.round(totalInterestCalc),
        totalPayment: Math.round(totalPaymentCalc),
        firstMonthPayment: Math.round(firstMonth),
        lastMonthPayment: Math.round(lastMonth),
      };
    }, [input]);

  return (
    <div className="app-container">
      <header className="header">
        <h1>住宅ローンシミュレーター</h1>
        <p>借入額や金利を入力して、毎月の返済額や返済推移を確認できます。</p>
      </header>

      <div className="simulator-layout">
        <LoanForm input={input} onChange={setInput} />

        <div>
          <div className="result-summary">
            <div className="summary-card">
              <div className="summary-title">
                {input.repaymentType === "equal-principal-and-interest"
                  ? "毎月の返済額"
                  : "初回返済額 (最終月)"}
              </div>
              <div className="summary-value">
                {monthlyPayment.toLocaleString()} 円
                {input.repaymentType === "equal-principal" && (
                  <span style={{ fontSize: "0.8rem", color: "var(--text-muted)", display: "block" }}>
                    最終月: {lastMonthPayment.toLocaleString()} 円
                  </span>
                )}
              </div>
            </div>

            <div className="summary-card">
              <div className="summary-title">総支払額</div>
              <div className="summary-value">{totalPayment.toLocaleString()} 円</div>
            </div>

            <div className="summary-card">
              <div className="summary-title">利息総額</div>
              <div className="summary-value">{totalInterest.toLocaleString()} 円</div>
            </div>
          </div>

          <LoanChart schedule={schedule} />
        </div>
      </div>
    </div>
  );
}
